--   Formatter:  clang-format   → lua/additions/formatting.lua
--   Debugger:   codelldb       → lua/additions/dap.lua
--   Mason:      clangd, clang-format, codelldb → lua/additions/mason.lua
--   Treesitter: c, cpp         → lua/additions/treesitter.lua
